Object.assign(loreEnglish, baseEnglish, revisionEnglish, reviewEnglish, lifeEnglish, socialPlacesEnglish, hubEnglish, leisureEnglish, navigationEnglish);
// Derived directory snippets and alternative text follow the same canonical translations.
const english = text => loreEnglish[text.replace(/\s+/g, ' ').trim()] || text;
const firstSentence = text => text.split(/(?<=\.)\s+/)[0];
factions.forEach((f, i) => add(`Dossier ${String(i + 1).padStart(2, '0')} / ${f.kind}`, `Dossier ${String(i + 1).padStart(2, '0')} / ${english(f.kind)}`));
[...zones, ...leisureDossiers].forEach(z => {
  add(firstSentence(z.description), firstSentence(english(z.description)));
  add(`${z.name}, ${z.level}`, `${english(z.name)}, ${english(z.level)}`);
});
people.forEach(p => {
  add(`Portrait de ${p.name}, ${p.role}`, `Portrait of ${english(p.name)}, ${english(p.role)}`);
  if (p.portraitKind === 'infrastructure') add(`${p.name} : infrastructure distribuée`, `${english(p.name)}: distributed infrastructure`);
});
